function resultRow(p){return `<button class="safari-result" data-safari-page="${p.id}"><span class="safari-result-icon ${p.id==='games'?'safari-game-art':''}">${picture(p)}</span><span><strong>${esc(p.title)}</strong><small>${esc(p.description)}</small><em>${p.kind==='page'?`portfolio://${p.id}`:esc(p.url)}</em></span><b>↗</b></button>`}
