viewport.id='safari-tab-content';address.value=routeAddress(r);$('#safari-reopen').hidden=!closed.length;$('#safari-back').disabled=t.position===0;$('#safari-forward').disabled=t.position===t.history.length-1;$('#safari-bookmark').disabled=!p;$('#safari-bookmark').setAttribute('aria-pressed',!!p&&fav.includes(p.id));$('#safari-bookmark').textContent=p&&fav.includes(p.id)?'★':'☆';$('#safari-bookmark').setAttribute('aria-label',p&&fav.includes(p.id)?'Remove from favourites':'Add to favourites');suggestions.hidden=true;
if(r.type==='home'){viewport.innerHTML=`<section class="safari-start"><div class="safari-start-heading"><span>SAFARI / MY CORNER OF THE INTERNET</span><img src="assets/princewill-linkedin.jpg" alt="Princewill Okube"><h1>A little curiosity.<br><em>A lot to explore.</em></h1><p>Projects, ideas and all the places you’ll find me.</p></div><form class="safari-start-search"><svg><use href="#i-search"/></svg><input aria-label="Search all my pages" placeholder="Try ‘CV help’, ‘IlluminatED’ or ‘YouTube’"><button aria-label="Search pages">↗</button></form><section class="safari-motion-stories"><h2>In motion <span>My public project videos · sound off</span></h2><div>${['clone-own','spider-sense'].map(id=>{const p=lookup(id);return `<article><video autoplay muted loop playsinline controls preload="auto" poster="${p.image}"><source src="${p.video}" type="video/mp4"></video><button data-safari-page="${id}"><strong>${p.title}</strong><span>Open project ↗</span></button></article>`}).join('')}</div></section><section><h2>Favourites <span>${fav.length} good places to start</span></h2><div class="safari-favourites">${fav.map(id=>tile(lookup(id))).join('')||'<p>Use the star in the toolbar to save a page here.</p>'}</div></section><section><h2>Made by me <span>Ideas out in the world</span></h2><div class="safari-made">${['illumed-site','testify-site','games'].map(id=>{const p=lookup(id);return `<button data-safari-page="${id}"><div>${id==='games'?'<img src="assets/game-covers/sonic.png" alt="Concept artwork for Sonic Burst 2">':picture(p)}</div><span><strong>${p.title}</strong><small>${p.description}</small></span><b>↗</b></button>`}).join('')}</div></section>${recent.length?`<section><h2>Recently visited</h2><div class="safari-recent">${recent.slice(0,5).map(id=>`<button data-safari-page="${id}">${esc(lookup(id).title)} <span>↗</span></button>`).join('')}</div></section>`:''}<section class="safari-all-pages"><h2>Everything in one place <span>Projects, games, services & socials</span></h2><div class="safari-favourites">${pages.map(tile).join('')}</div></section><p class="safari-start-note">Search is just for my pages. Open any external destination with its Visit link.</p></section>`;}
