$('#safari-page-status').textContent=r.type==='home'?`${pages.length} pages to explore`:p?.kind==='page'?'Portfolio page':p?'Destination preview · use Visit to open':`${results(r.query).length} search results`;
viewport.querySelectorAll('video').forEach(v=>{v.muted=true;v.playsInline=true;v.addEventListener('playing',()=>window.dispatchEvent(new CustomEvent('portfolio:notification',{detail:{title:'Video playing',body:'A project video is playing with sound off in Safari.',action:'safari'}})),{once:true});if(shell.open)v.play().catch(()=>{})});viewport.scrollTop=0;shell.classList.remove('safari-navigating');void shell.offsetWidth;shell.classList.add('safari-navigating');$('.safari-tab.selected')?.scrollIntoView({block:'nearest',inline:'nearest'});
