function navigate(route){const t=tab();t.history=t.history.slice(0,t.position+1);t.history.push(route);t.position++;if(route.type==='page')recent=[route.id,...recent.filter(id=>id!==route.id)].slice(0,6);render();viewport.focus({preventScroll:true})}
function findRoute(value){const q=value.trim();if(!q)return home();const key=q.replace(/^portfolio:\/\//i,'').replace(/^#/, '').replace(/\/$/,'').toLowerCase();const direct=lookup(key);if(direct)return page(direct.id);let url;try{url=new URL(q.includes('://')?q:'https://'+q)}catch{}
if(url){if(url.origin===location.origin){const id=url.hash.slice(1);if(lookup(id))return page(id);if(url.pathname.endsWith('games.html'))return page('games')}const match=pages.find(p=>p.url.startsWith('https:')&&p.url.replace(/\/$/,'').toLowerCase()===url.href.replace(/\/$/,'').toLowerCase());if(match)return page(match.id)}return {type:'search',query:q.slice(0,200)}}
function newTab(route=home()){const t={id:++count,history:[route],position:0};tabs.push(t);active=t.id;render();address.focus();address.select()}
function closeTab(id){const idx=tabs.findIndex(t=>t.id===id);if(idx<0)return;closed.push(tabs[idx]);if(closed.length>20)closed.shift();tabs.splice(idx,1);if(!tabs.length){tabs=[{id:++count,history:[home()],position:0}];active=count}else if(active===id)active=tabs[Math.min(idx,tabs.length-1)].id;render()}
function showSuggestions(){const q=address.value.trim();if(!q){suggestions.hidden=true;return}const matches=results(q).slice(0,6);suggestions.innerHTML=`<span>TOP MATCHES · MY PAGES</span>${matches.map(resultRow).join('')||'<p>No saved page matches. Press Enter to search the portfolio.</p>'}`;suggestions.hidden=false}
function close(minimise=false){const done=()=>{viewport.querySelectorAll('video').forEach(v=>v.pause());shell.close();dock.classList.toggle('is-minimised',minimise);dock.classList.toggle('is-running',minimise);dock.focus()};if(window.MacDesktopMotion)window.MacDesktopMotion.close(shell,dock,minimise,done);else done()}
window.openSafari=()=>{if(!isUnlocked)return;window.MacDesktopMotion?.cancel(shell);if(spotlight.open)spotlight.close();if(!shell.open){shell.show();render();bounceIcon(dock);if(window.MacDesktopMotion)window.MacDesktopMotion.open(shell,dock);else if(!reducedMotion.matches&&!document.body.classList.contains('reduce-motion'))shell.animate([{opacity:0,transform:'translateY(45px) scale(.88)',filter:'blur(7px)'},{opacity:1,transform:'translateY(0) scale(1)',filter:'blur(0)'}],{duration:480,easing:'cubic-bezier(.2,.8,.2,1)'})}viewport.querySelectorAll('video').forEach(v=>{v.muted=true;v.play().catch(()=>{})});dock.classList.add('is-running');dock.classList.remove('is-minimised');window.dispatchEvent(new CustomEvent('portfolio:desktop-window',{detail:{app:'safari'}}));address.focus();address.select()};
