$('#safari-close').onclick=()=>close();$('#safari-minimise').onclick=()=>close(true);$('#safari-maximise').onclick=()=>{shell.classList.toggle('safari-maximised');shell.style.transform='';shell.style.left='';shell.style.top='';shell.style.margin='';};$('#safari-add').onclick=()=>newTab();$('#safari-close-current').onclick=()=>closeTab(active);$('#safari-close-window').onclick=()=>close();$('#safari-reopen').onclick=()=>{if(!closed.length)return;const t=closed.pop();tabs.push(t);active=t.id;render()};$('#safari-home').onclick=()=>navigate(home());$('#safari-reload').onclick=render;$('#safari-back').onclick=()=>{if(tab().position>0){tab().position--;render()}};$('#safari-forward').onclick=()=>{if(tab().position<tab().history.length-1){tab().position++;render()}};
$('#safari-bookmark').onclick=()=>{const r=current();if(r.type!=='page')return;fav=fav.includes(r.id)?fav.filter(id=>id!==r.id):[...fav,r.id];try{localStorage.setItem('po-safari-favourites',JSON.stringify(fav))}catch{}render()};
shell.addEventListener('click',e=>{const route=e.target.closest('[data-safari-page]'),select=e.target.closest('[data-safari-tab]'),remove=e.target.closest('[data-safari-close-tab]'),internal=e.target.closest('[data-open]'),enquire=e.target.closest('[data-enquire]'),link=e.target.closest('a');if(route){if(e.metaKey||e.ctrlKey)newTab(page(route.dataset.safariPage));else navigate(page(route.dataset.safariPage))}else if(select){active=Number(select.dataset.safariTab);render();$(`[data-safari-tab="${active}"]`).focus()}else if(remove){closeTab(Number(remove.dataset.safariCloseTab))}else if(e.target.closest('[data-safari-home]'))navigate(home());else if(internal||enquire){e.stopPropagation();navigate(page(enquire?'contact':internal.dataset.open));if(enquire){const input=viewport.querySelector('[name="topic"]');if(input){const topic=enquire.dataset.enquire;input.value=[...input.options].some(o=>o.value===topic)?topic:/CV|career/i.test(topic)?'CV & LinkedIn support':/brand|content/i.test(topic)?'Brand collaboration':'Something else'}}}else if(link&&!link.classList.contains('safari-visit')){const match=pages.find(p=>p.url===link.getAttribute('href'));if(match){e.preventDefault();navigate(page(match.id))}}if(!e.target.closest('#safari-address-form,#safari-suggestions'))suggestions.hidden=true;});
shell.addEventListener('submit',async e=>{if(e.target.classList.contains('safari-start-search')){e.preventDefault();navigate(findRoute(e.target.querySelector('input').value));return}if(!e.target.classList.contains('brief-form'))return;e.preventDefault();e.stopPropagation();const form=e.target,data=new FormData(form),text=`Hi Princewill,\n\nI’m ${data.get('name')}. I’d like to discuss ${data.get('topic').toLowerCase()}.\n\n${data.get('idea')}\n\nLet me know a good time to chat.`,prepared=form.querySelector('textarea[readonly]'),feedback=form.querySelector('[aria-live]');prepared.value=text;prepared.hidden=false;try{await navigator.clipboard.writeText(text);feedback.textContent='Brief copied. Open LinkedIn below and paste it into your message.'}catch{feedback.textContent='Your brief is ready below. Select and copy it, then send it on LinkedIn.';prepared.focus();prepared.select()}});
shell.addEventListener('keydown',e=>{const command=e.metaKey||e.ctrlKey,key=e.key.toLowerCase();if(command&&['l','k','t','w'].includes(key)){e.preventDefault();e.stopPropagation();if(key==='l'||key==='k'){address.focus();address.select()}if(key==='t'){if(e.shiftKey&&closed.length){const t=closed.pop();tabs.push(t);active=t.id;render()}else newTab()}if(key==='w')closeTab(active)}if(e.altKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();e.stopPropagation();$(e.key==='ArrowLeft'?'#safari-back':'#safari-forward').click()}if(e.target.closest('#safari-suggestions')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const buttons=[...suggestions.querySelectorAll('button')],i=buttons.indexOf(e.target.closest('button'));buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}if(e.key==='Escape'&&suggestions.hidden){e.preventDefault();e.stopPropagation();close();return}if(e.key==='Escape'&&!suggestions.hidden){e.preventDefault();e.stopPropagation();suggestions.hidden=true;address.focus()}if(e.target.matches('[data-safari-tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const i=tabs.findIndex(t=>t.id===active);active=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length].id;render();$(`[data-safari-tab="${active}"]`).focus()}});
