$('.safari-toolbar').addEventListener('pointerdown',e=>{if(e.target.closest('button,input,form')||innerWidth<701||shell.classList.contains('safari-maximised'))return;const box=shell.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:box.left,top:box.top};e.currentTarget.setPointerCapture(e.pointerId)});$('.safari-toolbar').addEventListener('pointermove',e=>{if(!drag)return;shell.style.margin='0';shell.style.left=Math.max(0,Math.min(innerWidth-200,drag.left+e.clientX-drag.x))+'px';shell.style.top=Math.max(32,Math.min(innerHeight-100,drag.top+e.clientY-drag.y))+'px'});for(const event of ['pointerup','pointercancel'])$('.safari-toolbar').addEventListener(event,()=>drag=null);
